    "Unable to prepare memory.": "\u092e\u0947\u092e\u094b\u0930\u0940 \u0924\u0948\u092f\u093e\u0930 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0940\u0964",
    "Unable to refresh memory.": "\u092e\u0947\u092e\u094b\u0930\u0940 \u0930\u093f\u092b\u094d\u0930\u0947\u0936 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0940\u0964",
    "Unable to update memory.": "\u092e\u0947\u092e\u094b\u0930\u0940 \u0905\u092a\u0921\u0947\u091f \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0905\u0938\u092e\u0930\u094d\u0925\u0964",
    "Unable to update the sandbox setting.": "\u0938\u0948\u0902\u0921\u092c\u0949\u0915\u094d\u0938 \u0938\u0947\u091f\u093f\u0902\u0917 \u0905\u092a\u0921\u0947\u091f \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0940\u0964",
    "Unable to update web access.": "\u0935\u0947\u092c \u090f\u0915\u094d\u0938\u0947\u0938 \u0905\u092a\u0921\u0947\u091f \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u093e\u0964",
    "Unavailable": "\u0905\u0928\u0941\u092a\u0932\u092c\u094d\u0927",
    "Unexpected response format. Please check if your account was deleted.": "\u0905\u0928\u092a\u0947\u0915\u094d\u0937\u093f\u0924 \u0930\u093f\u0938\u094d\u092a\u0949\u0928\u094d\u0938 \u092b\u093c\u0949\u0930\u094d\u092e\u0948\u091f\u0964 \u0915\u0943\u092a\u092f\u093e \u091c\u093e\u0902\u091a\u0947\u0902 \u0915\u093f \u0906\u092a\u0915\u093e \u0916\u093e\u0924\u093e \u0939\u091f\u093e\u092f\u093e \u0917\u092f\u093e \u0939\u0948 \u092f\u093e \u0928\u0939\u0940\u0902\u0964",
