    "Upgrade to access Undetectable mode": "\u0905\u0928\u0921\u093f\u091f\u0947\u0915\u094d\u091f\u0947\u092c\u0932 \u092e\u094b\u0921 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0905\u092a\u0917\u094d\u0930\u0947\u0921 \u0915\u0930\u0947\u0902",
    "Upload an image": "\u090f\u0915 \u091b\u0935\u093f \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902",
